// Write a C++ function `int canPlaceChessboard(int whiteRows, int whiteCols, int blackRows, int blackCols)` that returns 1 if a white rectangle of size `whiteRows × whiteCols` and a black rectangle of size `blackRows × blackCols` can both fit on a chessboard without overlapping, given that they must be placed with at least 2 empty rows between them horizontally and at least 2 empty columns between them vertically (i.e., the gap between the two rectangles must be at least 2 rows and 2 columns in that respective dimension). The two rectangles must be axis-aligned and non-overlapping; they can be placed anywhere on an infinite grid, and their orientations are fixed (no rotation). The function returns 1 if it is possible to place them satisfying the gap requirement, otherwise 0. Inputs are positive integers between 1 and 10^9. Note that the gap is measured as the number of empty rows/columns between the rectangles, so if the white rectangle occupies rows 0–(whiteRows-1) and the black rectangle occupies rows (whiteRows+gap) to (whiteRows+gap+blackRows-1), the gap must be at least 2, meaning the distance between their edges must be ≥2. Similarly for columns.

#include <cassert>

int canFitWithMargin(int, int, int, int); // forward declaration

int main() {
    // Basic positive cases
    assert(canFitWithMargin(5, 5, 3, 3) == 1); // margin 2 each side fits
    assert(canFitWithMargin(4, 4, 2, 2) == 1); // exactly 2 margin (1 top/bottom, 1 left/right)
    // Negative cases
    assert(canFitWithMargin(4, 5, 3, 2) == 0); // height margin insufficient (4-3=1)
    assert(canFitWithMargin(5, 4, 2, 3) == 0); // width margin insufficient
    assert(canFitWithMargin(3, 3, 3, 3) == 0); // no margin at all
    assert(canFitWithMargin(5, 5, 4, 4) == 0); // only 1 margin total (needs 2)
    // Large input edge (no overflow)
    assert(canFitWithMargin(1000000000, 1000000000, 999999998, 999999998) == 1); // difference 2
    assert(canFitWithMargin(1000000000, 1000000000, 999999999, 999999998) == 0); // height difference 1
    return 0;
}

#include <cstdint>

// Determine if a rectangle of size smallRows x smallCols can be placed
// inside a rectangle of size largeRows x largeCols with at least one
// unit of margin on every side (total margin >= 2 in each dimension).
// Returns 1 if possible, 0 otherwise.
int canFitWithMargin(int largeRows, int largeCols, int smallRows, int smallCols) {
    // Use 64-bit arithmetic to avoid overflow for inputs up to 1e9.
    const int64_t requiredRows = static_cast<int64_t>(smallRows) + 2;
    const int64_t requiredCols = static_cast<int64_t>(smallCols) + 2;
    return (largeRows >= requiredRows && largeCols >= requiredCols) ? 1 : 0;
}

